reviews=[]
def review(id,items,degree,blockers,application,summary,eligibility=None):
 j=jobs[id]; req=[]
 for n,(text,status,ids,why,essential) in enumerate(items,1):
  req.append(dict(id=f'{id}-deep-{n}',text=text,assessment=status,evidenceIds=ids.split() if ids else [],explanation=why,essential=essential))
 reviews.append(dict(jobId=id,company=j['company'],title=j['title'],reviewedAt=now,sourceUrl=j['url'],requirements=req,degreeRequirement=degree,missingFacts=blockers,application=application,summary=summary,applicationReady=False,eligibility=eligibility or j['eligibility'],eligibilityEvidence=j['eligibilityEvidence']))
def R(text,ids,why,essential=True):return(text,'met',ids,why,essential)
def U(text,ids,why,essential=True):return(text,'unknown',ids,why,essential)
def G(text,why,essential=False):return(text,'gap','',why,essential)
