actions=[]
for r in reviews:
 j=jobs[r['jobId']]
 notes=j['notes']+'\n\nDeep review '+now+': '+r['summary']+'\nDegree: '+r['degreeRequirement']+'\nOpen facts: '+'; '.join(r['missingFacts'])+'\nApplication route: '+json.dumps(r['application'],ensure_ascii=False)+'\nTechnical fit and eligibility are separate. No application or outreach has been sent.'
 research=json.loads(json.dumps(j['research']))
 research['sources'].append(dict(id=j['id']+'-deep-review',label='Full official JD and application-route review',url=j['url'],text='All visible qualifications were reviewed. '+r['summary']+' '+r['degreeRequirement']+' Application checks: '+r['application']['inspection'],capturedAt=now,screenshotUrl='',screenshotPath=''))
 actions.append(dict(type='update_job',id=j['id'],patch=dict(requirements=r['requirements'],notes=notes,research=research,eligibility=r['eligibility'],eligibilityEvidence=r['eligibilityEvidence'],priority='high' if j['id'].startswith('yc-') else 'medium',nextAction=r['missingFacts'][0])))
(D/'reviewed-actions-kanban.json').write_text(json.dumps(actions,indent=2,ensure_ascii=False)+'\n')
(D/'reviewed-notes-kanban.json').write_text(json.dumps(dict(preparedAt=now,scope='Local review only; eight existing jobs; no application, outreach or cloud mutation.',method='Full official descriptions matched against candidate-provided resume and portfolio. Technical fit is separate from immigration/office arrangements. General professional skills use concrete delivery evidence; unreported tools remain unknown. Employer interview verification is still required.',candidateSources=['.job-search/resumes/masters/facts.json','.job-search/flowcv-resume-source.txt','content/site.ts','content/projects.ts'],jobs=reviews),indent=2,ensure_ascii=False)+'\n')
print('Prepared',len(actions),'local review actions')
